using NAudio.Wave;
using System.Text.Json;
namespace DiscordDeck;
static class ImportTest {
 public static async Task Run(){var dir=Path.Combine(Path.GetTempPath(),"DeckTest-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);bool ok=false;string error="";try{var source=Path.Combine(dir,"source.wav");using(var writer=new WaveFileWriter(source,new WaveFormat(44100,16,1))){for(int i=0;i<44100*3;i++){var bytes=BitConverter.GetBytes((short)(Math.Sin(i*2*Math.PI*440/44100)*3000));writer.Write(bytes,0,2);}}var dest=Path.Combine(dir,"clip.mp3");await YouTubeImport.Trim(source,dest,.5,1.75,CancellationToken.None);using(var reader=new AudioFileReader(dest)){if(Math.Abs(reader.TotalTime.TotalSeconds-1.25)>.15)throw new Exception("Clip duration incorrect");}try{await YouTubeImport.Trim(source,dest,2,1,CancellationToken.None);throw new Exception("Invalid range accepted");}catch(ArgumentException){}try{await YouTubeImport.Download("https://youtube.com.evil.invalid/watch?v=test",dir,CancellationToken.None);throw new Exception("Invalid host accepted");}catch(ArgumentException){}using var cancel=new CancellationTokenSource();cancel.Cancel();try{await YouTubeImport.Trim(source,dest,0,1,cancel.Token);throw new Exception("Cancellation ignored");}catch(OperationCanceledException){}ok=true;}catch(Exception e){error=e.ToString();}finally{Directory.Delete(dir,true);}File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"import-test.json"),JsonSerializer.Serialize(new{ok,error}));if(!ok)Environment.ExitCode=1;}
 public static async Task Download(string[] urls){var results=new List<object>();foreach(var u in urls){var dir=Path.Combine(Path.GetTempPath(),"DeckDl-"+Guid.NewGuid().ToString("N"));try{var f=await YouTubeImport.Download(u,dir,CancellationToken.None);double secs;using(var r=new AudioFileReader(f))secs=r.TotalTime.TotalSeconds;results.Add(new{url=u,ok=secs>0,file=Path.GetFileName(f),secs});}catch(Exception e){results.Add(new{url=u,ok=false,error=e.Message});}finally{try{Directory.Delete(dir,true);}catch{}}}File.WriteAllText(Path.Combine(Path.GetTempPath(),"deck-download-test.json"),JsonSerializer.Serialize(results,new JsonSerializerOptions{WriteIndented=true}));}
}
